# ============================================================================
# R²-SFT warm-up scorer — 200 step SFT for PPL scorer
# ============================================================================
# Data: r2sft_warmup_raw.json
#   (generated by data/onerec_data/sft/cot/3_ppl_eval/main_version/0_build_warmup_data.sh)
#   - raw CoT (video + ad, unfiltered)
#   - non-CoT rec (video + ad)
#   - caption2sid + sid2caption (video + ad)
#   - SPLIT_TARGET=1, TARGET_MAX_LEN=3
#
# Purpose: train a 200-step SFT model as the SID-PPL scorer for the downstream
# PPL filtering step.
#
# Training params (identical to the main SFT except checkpoint interval/stop step):
#   - num_training_steps=6600 (lr scheduler shape kept from main recipe)
#   - save_checkpoint_per_step=200 (only need step200 ckpt)
#   - lr=5e-6, min_lr=1e-7, weight_decay=0.1, cosine, warmup=50
#   - ENABLE_TARGET_LOSS=1
# ============================================================================

MODEL_DIR="${MODEL_DIR:-../models/pretrain-8B/converted}"
OUTPUT_DIR="${OUTPUT_DIR:-../models/r2sft_warmup_200steps}"
LOSS_IMPL=${LOSS_IMPL:-ce_v2}
ENABLE_TARGET_LOSS=${ENABLE_TARGET_LOSS:-1}
TARGET_LOSS_BETA=${TARGET_LOSS_BETA:-1.0}
TARGET_LOSS_SOURCES_NAME=${TARGET_LOSS_SOURCES_NAME:-"RecIF_RecCOT"}

DATASET_CONFIG=${DATASET_CONFIG:-examples/dataset_config/r2sft_warmup_raw.json}

mkdir -p "$OUTPUT_DIR"
mkdir -p /tmp/_wids_cache

HOSTFILE="${HOSTFILE:-/etc/mpi/hostfile}"
nnode=$(wc -l < "$HOSTFILE")

set -x

SCRIPT_FILE=$(readlink -f $0)
echo `date '+%Y-%m-%d %H:%M:%S'` >> $OUTPUT_DIR/task_info.log
echo "script: ${SCRIPT_FILE}" >> $OUTPUT_DIR/task_info.log
echo "=========================" >> $OUTPUT_DIR/task_info.log

echo "Output: $OUTPUT_DIR"

export PYTHONPATH=$PWD:$PYTHONPATH

source set_env.sh

TCP_NIC="${TCP_NIC:-$(ifconfig 2>/dev/null | grep -B1 " $(hostname -i) " | grep -o "^\w*" | head -n1)}"
TCP_NIC="${TCP_NIC:-eth0}"
MASTER_ADDR="${MASTER_ADDR:-${MY_NODE_IP:-127.0.0.1}}"
MASTER_PORT="${MASTER_PORT:-8499}"

mpirun --allow-run-as-root \
    -hostfile "$HOSTFILE" \
    -mca btl self,tcp -mca pml ob1 \
    -mca btl_tcp_if_include "$TCP_NIC" \
    -mca oob_tcp_if_include "$TCP_NIC" \
    -mca btl_openib_allow_ib false \
    -x OMPI_MCA_btl=self,tcp \
    -x OMPI_MCA_pml=ob1 \
    -x OMPI_MCA_btl_tcp_if_include="$TCP_NIC" \
    -x OMPI_MCA_oob_tcp_if_include="$TCP_NIC" \
    -x OMPI_MCA_btl_openib_allow_ib=false \
    -x NCCL_IB_DISABLE=0 \
    -x NCCL_IB_GID_INDEX=3 \
    -x NCCL_SOCKET_IFNAME="$TCP_NIC" \
    -x NCCL_IB_HCA=mlx5 \
    -x NCCL_DEBUG=WARN \
    -x NCCL_IB_QPS_PER_CONNECTION=4 \
    -x NCCL_IB_TIMEOUT=20 \
    -x LD_PRELOAD="${LD_PRELOAD:-}" \
    -x http_proxy="" \
    -x https_proxy="" \
    -x HOROVOD_MPI_THREADS_DISABLE=1 \
    -x MPI_THREAD_SINGLE=1 \
    -x NO_COLOR=1 \
    -x TERM=dumb \
    -x COLORTERM=0 \
    -x PYTHONIOENCODING=utf-8 \
    -x LD_LIBRARY_PATH="${LD_LIBRARY_PATH:-}" \
    -x PATH \
    -x PYTHONPATH="$PYTHONPATH" \
    -x JAVA_HOME="${JAVA_HOME:-}" \
    -x HIVE_HOME="${HIVE_HOME:-}" \
    -x CLASSPATH="${CLASSPATH:-}" \
    -x HADOOP_USER_NAME="${HADOOP_USER_NAME:-}" \
    -x HADOOP_HOME="${HADOOP_HOME:-}" \
    -x SPARK_HOME="${SPARK_HOME:-}" \
    -x MASTER_ADDR="$MASTER_ADDR" \
    -x MASTER_PORT="$MASTER_PORT" \
    -x TOKENIZERS_PARALLELISM=false \
    bash -c "python3 recipes/train_qwen3.py \
        --model_dir $MODEL_DIR \
        --output_dir $OUTPUT_DIR \
        --dataset_config $DATASET_CONFIG \
        --model_class Qwen3ForCausalLM \
        --loss_impl $LOSS_IMPL \
        --enable_target_loss $ENABLE_TARGET_LOSS \
        --target_loss_beta $TARGET_LOSS_BETA \
        --target_loss_sources_name \"$TARGET_LOSS_SOURCES_NAME\" \
        --monitor_datasource_loss \
        --monitor_datasource_cnt \
        --max_length 32768 \
        --learning_rate 5e-6 \
        --min_lr 1e-7 \
        --weight_decay 0.1 \
        --lr_scheduler_type cosine \
        --num_warmup_steps 50 \
        --num_training_steps 6600 \
        --save_checkpoint_per_step 200 \
        --minibatch_size 4096 \
        --logging_per_step 5 \
        --use_fp32_weight \
        --max_grad_norm 1.0 \
        --seed 19260817 \
        --enable_profiler \
        --enable_gradient_checkpointing \
        --use_chunked_loss_computer \
    " > $OUTPUT_DIR/stdout.log 2>$OUTPUT_DIR/stderr.log &

# num_training_steps=6600 keeps the main-recipe lr scheduler shape; save_checkpoint_per_step=200
# yaml max_step=200 → auto_train stops after step200/converted.
